mapper.select:
SELECT tdm12_task_relate_detail_id AS task_relate_detail_id , tdm12_task_id AS task_id , '('||tdm14_task_type_cd||')'||tdm14_task_type_nm AS task_type_name , tdm10_task_nm AS task_name , tdm10_start_date AS task_start_date , tdm10_end_date AS task_end_date , tdm12_content AS content , tdm12_use_yn AS use_yn , ( SELECT CASE WHEN COUNT(*) = 0 THEN '' ELSE COUNT(*)||'건' END FROM tdm13_task_relate_duty WHERE tdm13_task_relate_detail_id = tdm12_task_relate_detail_id ) AS duty_cnt FROM tdm12_task_relate_detail INNER JOIN tdm10_task ON tdm10_task_id = tdm12_task_id INNER JOIN tdm14_task_type ON tdm10_company_id = tdm14_company_id AND tdm14_task_type_cd = tdm10_task_type_cd WHERE tdm10_company_id = #{companyId}
AND CAST(#{baseDate} AS date) BETWEEN tdm10_start_date AND COALESCE(tdm10_end_date, TO_DATE('29991231','yyyyMMdd')) AND tdm12_use_yn = 'true'
AND tdm14_task_type_cd LIKE #{taskTypeCode} AND CONCAT(tdm10_task_nm, tdm12_content) ILIKE #{searchText} ORDER BY tdm10_task_type_cd , tdm10_task_nm COLLATE "ko_KR.utf8" , tdm10_start_date , tdm12_seq

SELECT (
        SELECT  COUNT(*)
          FROM  tdm43_manl
         WHERE  tdm43_task_relate_duty_id = #{dutyId}
       ) + (
        SELECT  COUNT(*)
          FROM  tdm35_role_allc_task
                INNER JOIN tdm34_role_allc_detail ON tdm34_role_allc_detail_id = tdm35_role_allc_detail_id
                INNER JOIN apr01_appr             ON (    apr01_appr_id = tdm34_appr_id
                                                      AND COALESCE(apr01_status_cd,'99') IN ('10','20','30') )
         WHERE  tdm35_task_relate_duty_id = #{dutyId}
       )

mapper.update:
UPDATE tdm13_task_relate_duty
   SET tdm13_content  = #{row.content}
     , tdm13_seq      = #{row.seq}
     , tdm13_use_yn   = #{row.useYn}
     , tdm13_upd_nm   = #{updName}
     , tdm13_upd_date = f_sysdate()
 WHERE tdm13_task_relate_duty_id = #{row.taskRelateDutyId}

mapper.delete:
DELETE FROM tdm13_task_relate_duty
 WHERE tdm13_task_relate_duty_id IN
#{id}
